update_rule.pseudocode:
if t == 0:
  set_random_seed(global.random_seed)
  N = init.population_size
  # Sample target degrees from lognormal to achieve mean and CV
  mu = log(mean_degree / sqrt(1 + degree_cv^2))
  sigma = sqrt(log(1 + degree_cv^2))
  for i in 1..N:
    k_i = max(1, round(LogNormal(mu, sigma)))
  # Adjust degrees to ensure even sum
  if sum(k_i) % 2 == 1:
    k_1 += 1
  # Build configuration model by pairing stubs uniformly at random
  G = configuration_model_from_degree_sequence(k_1..k_N)
  G = simple_undirected_graph(G)  # remove multi-edges/self-loops via rewire
  # Add small-world properties via rewiring and triadic closure
  for each edge (u, v) in G:
    with probability rewiring_probability:
      w = random_node_not_in({u} ∪ neighbors(u))
      rewire_edge((u, v) -> (u, w))
  # Triadic closure
  for each node u in G:
    for each unordered pair (v, w) in neighbors(u):
      if not edge(v, w) and random_uniform() < clustering_bias:
        add_edge(v, w)
  signal.network.graph = G
  signal.network.degrees = {i: degree(i) for i in nodes(G)}
else:
  no_op()

if t == 0:
  s_prev = media_base_intensity
else:
  s_prev = signal.media.intensity[t-1]
phi = media_persistence
sigma = media_volatility
s_t = media_base_intensity*(1 - phi) + phi*s_prev + Normal(0, sigma)
if random_uniform() < media_shock_prob:
  s_t += Normal(0, media_shock_scale)
signal.media.intensity[t] = s_t
